From f52c5b907def50eea263321c94f73bc091544b4e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:42:59 +0100
Subject: [PATCH] libs/editor: keep the default hotspot name within 32 bytes

The default hotspot name is the login name followed by "-hotspot", so with
a long login name it went over the 32 bytes allowed for an SSID and turning
on the hotspot failed. Now the login name is shortened until it fits.

BUG: 527192
---
 libs/editor/configuration.cpp | 8 +++++++-
 1 file changed, 7 insertions(+), 1 deletion(-)

diff --git a/libs/editor/configuration.cpp b/libs/editor/configuration.cpp
index 79c794d74..5499dd627 100644
--- a/libs/editor/configuration.cpp
+++ b/libs/editor/configuration.cpp
@@ -112,7 +112,13 @@ QString Configuration::hotspotName() const
     KConfigGroup grp(config, QStringLiteral("General"));
     KUser currentUser;

-    const QString defaultName = currentUser.loginName() + QLatin1String("-hotspot");
+    const QString suffix = QStringLiteral("-hotspot");
+    QString loginName = currentUser.loginName();
+    // An SSID can be at most 32 bytes long
+    while (!loginName.isEmpty() && (loginName + suffix).toUtf8().size() > 32) {
+        loginName.chop(1);
+    }
+    const QString defaultName = loginName + suffix;

     if (grp.isValid()) {
         return grp.readEntry(QStringLiteral("HotspotName"), defaultName);
-- 
